import React, { useState, useEffect } from 'react';
import './CartPage.css';
import { useNavigate } from 'react-router-dom';
import { useLocation } from 'react-router-dom';
import { useContext } from 'react';
import { UserContext } from '../context/UserContext'; // Import UserContext
import axios from 'axios';

const CartPage = () => {
    // const navigate = useNavigate();
    const location = useLocation();
    const { userId } = useContext(UserContext); // Get logged-in user's ID from context
    const [items, setItems] = useState([]);

    useEffect(() => {
        if (!userId) {
            // Redirect to login if user is not logged in
            navigate('/login');
        } else {
            // Fetch the user's cart items based on userId
            const fetchCartItems = async () => {
                try {
                    const response = await axios.get(`http://localhost:5000/cart/${userId}`);
                    setItems(response.data.cartItems); // Assuming the response contains cart items
                } catch (error) {
                    console.error('Error fetching cart items', error);
                }
            };
            fetchCartItems();
        }
    }, [userId, navigate]);

    const incrementQuantity = (id) => {
        setItems(items.map(item =>
            item.id === id ? { ...item, quantity: item.quantity + 1 } : item
        ));
    };

    const decrementQuantity = (id) => {
        setItems(items.map(item => {
            if (item.id === id && item.quantity > 1) {
                return { ...item, quantity: item.quantity - 1 };
            }
            return item;
        }));
    };

    const subtotal = items.reduce((total, item) => total + item.price * item.quantity, 0);

    return (
        <div className="cart-container">
            <div className="cart-items">
                <h2>MY CART</h2>
                {items.length === 0 ? (
                    <p>Your cart is empty.</p>
                ) : (
                    items.map(item => (
                        <div key={item.id} className="item">
                            <img src={item.imageUrl} alt={item.name} className="item-image" />
                            <div className="item-details">
                                <p className="item-name">{item.name}</p>
                                <div className="quantity-control">
                                    <button className="quantity-button" onClick={() => decrementQuantity(item.id)}>-</button>
                                    <span className="quantity">{item.quantity}</span>
                                    <button className="quantity-button" onClick={() => incrementQuantity(item.id)}>+</button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
            {items.length > 0 && (
                <div className="cart-subtotal">
                    <h2>CART SUBTOTAL</h2>
                    {items.map(item => (
                        <div key={item.id} className="subtotal-item">
                            <img src={item.imageUrl} alt={item.name} className="subtotal-image" />
                            <div className="subtotal-details">
                                <p>{item.name}</p>
                                <p>X{item.quantity}</p>
                                <p>Rs.{item.price * item.quantity}</p>
                            </div>
                        </div>
                    ))}
                    <div className="total">SUBTOTAL: Rs.{subtotal}</div>
                    <br />
                    <input className="checkout-button" type="button" value="Checkout" />
                </div>
            )}
        </div>
    );
};

export default CartPage;
